<section class="summary-grid"><?php foreach($summary as $s):$e=$s['employee'];$pay=$e['payroll']??[];$displayName=workforce_employee_display_name($e);$avatarUrl=workforce_employee_avatar_url($d,$e);$avatarFallback=trim(substr((string)($e['code']??''),0,3));if($avatarFallback==='')$avatarFallback=workforce_initial($displayName);?><article class="person-card<?=((int)($s['absent_count']??0)>0)?' has-absence':''?><?=((float)($s['penalty_confirmed']??0)>0)?' has-penalty':''?>"><div class="person-title"><div class="avatar profile-avatar"><span class="profile-avatar-fallback"><?=h($avatarFallback)?></span><?php if($avatarUrl!==''):?><img src="<?=h($avatarUrl)?>" alt="รูปโปรไฟล์ <?=h($displayName)?>" loading="lazy" decoding="async" onerror="this.remove()"><?php endif;?></div><div><b><?=h((string)$e['code'].' · '.$displayName)?></b><small><?=h(workforce_position_label((string)$e['position']))?> · <?=h(strtoupper((string)($pay['type']??'daily')))?> · เริ่ม <?=h((string)($pay['start_time']??'18:00'))?></small></div></div><div class="metric-group"><small class="metric-group-title">สรุปการมาทำงาน</small><div class="person-kpis primary"><span><b><?=number_format((int)($s['scheduled_days']??0))?></b> ตาราง</span><span><b><?=number_format((int)$s['days'])?></b> ทำงาน</span><span class="<?=($s['leave_days']??0)?'leave':''?>"><b><?=number_format((int)($s['leave_days']??0))?></b> ลา</span><span class="<?=($s['absent_count']??0)?'bad':''?>"><b><?=number_format((int)($s['absent_count']??0))?></b> ขาด</span><span class="<?=$s['late_count']?'late':''?>"><b><?=$s['late_count']?></b> สาย<small><?=($s['late_minutes']??0)>0?' '.number_format((int)$s['late_minutes']).' นาที':''?></small></span></div></div><div class="metric-group secondary"><small class="metric-group-title">เวลาและรายการตรวจสอบ</small><div class="person-kpis secondary"><span><b><?=h(pa_hm($s['minutes']))?></b> ชม.</span><span><b><?=h(pa_hm($s['ot']))?></b> OT</span><span class="<?=$s['missing_out']?'bad':''?>"><b><?=$s['missing_out']?></b> ไม่ออก</span><span class="<?=$s['pending_review']?'bad':''?>"><b><?=$s['pending_review']?></b> รอตรวจ</span><?php if((int)($s['substituted_days']??0)>0):?><span class="substitute"><b><?=number_format((int)$s['substituted_days'])?></b> มีคนแทน</span><?php endif;?></div></div><div class="estimate"><div class="estimate-main"><small>ประมาณการสุทธิช่วงนี้</small><strong><?=h(number_format((float)$s['estimate'],2))?> <?=h($currency)?></strong></div><?php if((float)($s['penalty_confirmed']??0)>0):?><span class="penalty-note">หัก No-show แล้ว <?=number_format((float)$s['penalty_confirmed'],2)?> <?=h($currency)?> · <?=number_format((int)($s['penalty_count']??0))?> ครั้ง</span><span class="gross-note">ก่อนหัก <?=number_format((float)($s['gross_estimate']??0),2)?> <?=h($currency)?></span><?php elseif((float)($s['penalty_pending']??0)>0):?><span class="penalty-note pending">ค่าปรับรอยืนยัน <?=number_format((float)$s['penalty_pending'],2)?> <?=h($currency)?></span><?php elseif((float)($s['penalty_candidate']??0)>0):?><span class="penalty-note candidate">พบ No-show รอสร้างรายการ <?=number_format((float)$s['penalty_candidate'],2)?> <?=h($currency)?> · <?=number_format((int)($s['penalty_candidate_count']??0))?> ครั้ง</span><?php endif;?></div><?php if(!empty($e['pr_id'])):$pc=$e['pr_compensation']??[];?><div class="pr-rate-summary"><span>ค่ากะ <?=h(number_format((float)($pay['daily_rate']??0),0))?></span><span>คอม/งาน <?=h(number_format((float)($pc['commission_rate']??0),0))?></span><span>ดื่ม/หน่วย <?=h(number_format((float)($pc['drink_rate']??0),0))?></span></div><?php endif;?><?php if($canManage):?><div class="pay-edit-link"><small>Rate แก้จาก Employee Center จุดเดียว</small><a href="employees.php?employee_id=<?=(int)$e['id']?>">แก้ค่าจ้างพนักงานคนนี้ →</a></div><?php endif;?></article><?php endforeach;?><?php if(!$summary):?><article class="empty-card">ยังไม่มี Attendance ในช่วงวันที่ที่เลือก</article><?php endif;?></section>
<section class="panel"><div class="section-head"><div><h2>ตารางเวลาทำงาน</h2><p>พนักงานทุกประเภท · รูปเล็กคลิกเพื่อขยาย</p></div><b><?=count($detail)?> รายการ</b></div><div class="table-wrap"><table><thead><tr><th>พนักงาน</th><th>วันที่ / สาขา</th><th>Check-In</th><th>Check-Out</th><th>เวลาทำงาน</th><th>OT</th><th>สาย</th><th>GPS</th><th>รูปยืนยัน</th><th>สถานะ</th><th>ประมาณการ</th></tr></thead><tbody><?php foreach($detail as $r):$a=$r['a'];$e=$r['employee'];$b=pa_branch($d,(int)($a['branch_id']??0));?><tr><td><b><?=h((string)$e['code'])?></b><small><?=h((string)$e['name'].' · '.workforce_position_label((string)$e['position']))?></small></td><td><b><?=h(date('d/m/Y',strtotime((string)$a['check_in'])))?></b><small><?=h((string)$b['name'])?></small></td><td class="time in"><?=h(date('H:i:s',strtotime((string)$a['check_in'])))?></td><td class="time out"><?=empty($a['check_out'])?'<span class="tag bad">ยังไม่ออกงาน</span>':h(date('H:i:s',strtotime((string)$a['check_out'])))?></td><td><b><?=h(pa_hm($r['worked']))?></b></td><td><?=h(pa_hm($r['ot']))?></td><td><?=$r['late']?'<span class="tag late">+'.(int)$r['late'].' นาที</span>':'<span class="tag ok">ตรงเวลา</span>'?></td><td><small>IN <?=isset($a['checkin_distance_m'])?round((float)$a['checkin_distance_m']).'m':'-'?> ±<?=isset($a['checkin_accuracy_m'])?round((float)$a['checkin_accuracy_m']).'m':'-'?></small><small>OUT <?=isset($a['checkout_distance_m'])?round((float)$a['checkout_distance_m']).'m':'-'?> ±<?=isset($a['checkout_accuracy_m'])?round((float)$a['checkout_accuracy_m']).'m':'-'?></small></td><td><div class="thumbs"><?php if(!empty($a['checkin_evidence'])):?><button class="thumb" type="button" data-src="<?=h(pa_evidence_url((int)$a['id'],'in'))?>" data-title="<?=h((string)$e['code'].' · Check-In · '.date('d/m/Y H:i:s',strtotime((string)$a['check_in'])))?>"><img loading="lazy" src="<?=h(pa_evidence_url((int)$a['id'],'in'))?>" alt="IN"></button><?php endif;?><?php if(!empty($a['checkout_evidence'])):?><button class="thumb" type="button" data-src="<?=h(pa_evidence_url((int)$a['id'],'out'))?>" data-title="<?=h((string)$e['code'].' · Check-Out · '.date('d/m/Y H:i:s',strtotime((string)$a['check_out'])))?>"><img loading="lazy" src="<?=h(pa_evidence_url((int)$a['id'],'out'))?>" alt="OUT"></button><?php endif;?><?php if(empty($a['checkin_evidence'])&&empty($a['checkout_evidence'])):?><span class="muted">ไม่มีรูป</span><?php endif;?></div></td><td><?php if(!$r['final']):?><span class="tag bad">Pending Review</span><small><?=h((string)$r['state'])?></small><?php else:?><span class="tag ok">Final</span><?php endif;?></td><td><b><?=h(number_format((float)$r['pay'],2))?></b><small><?=h($currency)?></small></td></tr><?php endforeach;?></tbody></table></div></section><footer>MR BAR Workforce Attendance & Payroll · <?=h((string)(app_config()['pack']??'MR BAR'))?> · Schema v<?=h((string)($d['meta']['schema']??24))?> · ตัวเลขค่าจ้างเป็นประมาณการ</footer></main><div class="photo-modal" id="photoModal" aria-hidden="true"><button class="modal-close" type="button">×</button><div class="modal-box"><img id="modalImage" alt="Attendance Evidence"><p id="modalTitle"></p></div></div><script src="assets/payroll.js?v=1200"></script></body></html>
